sksl:
uniform shader image;
uniform shader bright;
uniform shader blurred;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float blur;
uniform float threshold;
uniform float intensity;
layout(color) uniform half4 color;
uniform float opacity;
uniform float blend;
uniform float soften;
uniform float mask;
uniform float style;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (style > 0.5) {
        float2 u = (coord - screen.xy) * 0.5 - 0.5;
        float2 i = floor(u);
        float2 w = u - i;
        float2 b = screen.xy + 2.0 * i + 1.0;
        c = half4(mix(mix(float4(image.eval(b)), float4(image.eval(b + float2(2.0, 0.0))), w.x),
                      mix(float4(image.eval(b + float2(0.0, 2.0))), float4(image.eval(b + float2(2.0, 2.0))), w.x), w.y));
    }
    if (soften > 0.0) {
        float4 sum = float4(0.0);
        float total = 0.0;
        for (int y = -2; y <= 2; y++) {
            for (int x = -2; x <= 2; x++) {
                float w = exp(-float(x * x + y * y) / (2.0 * soften * soften));
                sum += float4(image.eval(coord + float2(float(x), float(y)))) * w;
                total += w;
            }
        }
        c = half4(sum / total);
    }
    half4 g = bright.eval(coord);
    float glow = clamp(float(g.r) * intensity * clamp(opacity, 0.0, 1.0) * (style > 0.5 ? 0.77 : 4.41), 0.0, 1.0);
    if (mask > 0.5) glow *= float(c.a);
    float3 tint = float3(color.rgb);
    if (blend < 1.0) {
        half4 s = blurred.eval(coord);
        float3 own = s.a > 0.0 ? float3(s.rgb) / float(s.a) : float3(1.0);
        own = own / max(max(own.r, max(own.g, own.b)), 0.0001);
        tint = mix(own, tint, clamp(blend, 0.0, 1.0));
    }
    float3 add = glow * tint * float(color.a);
    float a = float(c.a) + glow * float(color.a) * (1.0 - float(c.a));
    float3 rgb = float3(c.rgb) + add - float3(c.rgb) * add;
    return half4(half3(clamp(rgb, 0.0, a)), half(a));
}
